window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-f3b8cf223c55c71f"]={"versions": [{"id": "FIG-f3b8cf223c55c71f", "releases": ["R1.3.0", "R1.5.1", "R17-10_R1.2.0", "R18-10_R4.4.0_R1.5.0", "R19-03", "R19-11", "R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturelles Datenlayout- und Berechnungsdiagramm zur E2E-Kommunikationsabsicherung (AUTOSAR End-to-End Protocol Specification). Das Schaubild veranschaulicht die Byte- und Feldanordnung einer serialisierten Nachricht sowie den Datenfluss zur Berechnung der 8-Bit-Prüfsumme (CRC8) für das E2E-Profil 1 in der Variante 1A bei signalbasierter Kommunikation.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>DataId</strong>: Konfigurierte Identifikation des Datenstroms/der Botschaft, separat von der Nutzlast in die CRC-Berechnung einbezogen.\n</li><li><strong>CRC-Feld</strong>: 1-Byte-Feld (Byte 0, Bit-Offset 0) zur Aufnahme der resultierenden Prüfsumme.\n</li><li><strong>Alive Counter / Nibble 0xF</strong>: 1 Byte (Byte 1), unterteilt in das obere Halbbyte mit dem statischen Bitmuster <code>0xF</code> (entsprechend <code>unusedBitPattern = 0xFF</code>) und das untere Halbbyte mit dem dynamischen 4-Bit-Zähler (<code>Counter</code>, Bit-Offset 8 bis 11).\n</li><li><strong>Sig1 / Nutzsignale</strong>: Serialisierte Nutzsignalbereiche über mehrere Byteblöcke.\n</li><li><strong>Leere Bereiche / Unused Bits (<code>0xFF</code>, Leerfelder)</strong>: Nicht durch Nutzsignale belegte Bytes bzw. Padding-Bereiche innerhalb des Datenbereichs.\n</li><li><strong>Berechnungsvorschrift</strong>: <code>CRC := CRC8 over (1) Data Id, (2) all serialized signal (including empty areas, excluding CRC byte itself)</code>.\n</li><li><strong>Eingangsschnittstelle für Berechnung</strong>: Geschweifte Klammer spannt über den gesamten Datenstrom ab Byte 1 (unter Ausschluss des CRC-Bytes) und wird zusammen mit <code>DataId</code> über gerichtete Pfeile in das CRC-Byte zurückgeführt.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Zusammensetzen bzw. Serialisieren der Nutzsignale (<code>Sig1</code>) und des aktuellen Alive-Counters (<code>Counter</code> im unteren Nibble von Byte 1 mit <code>0xF</code> im oberen Nibble).\n</li><li>Auffüllen ungenutzter Byte- und Bitbereiche mit dem definierten Füllmuster (<code>0xFF</code> bzw. <code>0xF</code>).\n</li><li>Durchführung der CRC8-Berechnung über zwei Eingangsanteile:\n<ul class=\"fig-list\"><li>die vorkonfigurierte <code>DataId</code>,\n</li><li>alle serialisierten Signal- und Leerdaten ab Byte 1 bis zum Nachrichtenende (das CRC-Byte selbst wird explizit ausgespart).\n</li></ul>\n</li><li>Eintragen des berechneten 8-Bit-CRC-Wertes in Byte 0 der serialisierten Botschaft.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Normative Vorgabe zur Berechnung von E2E-Profil 1 (Variante 1A) unter Nutzung von <code>Crc_CalculateCRC8()</code>.\n</li><li>Das CRC-Byte belegt Byte 0 (Bit-Offset 0) und darf nicht selbst in die CRC-Prüfsumme einfließen.\n</li><li>Der Alive-Counter belegt die niederwertigen 4 Bits von Byte 1; ungenutzte Bits sind mit dem Muster <code>0xFF</code> zu belegen (<code>unusedBitPattern</code>).\n</li><li>Nicht signalbelegte Bytes (Leerbereiche) müssen im PDU-Puffer initialisiert und lückenlos in die Prüfsummenberechnung einbezogen werden.\n</li><li>Die <code>DataId</code> wird gemäß Konfigurationsmodus (z. B. <code>E2E_P01_DATAID_BOTH</code>) in die Prüfsummenberechnung eingespeist.\n</li></ul>"}, {"id": "FIG-ab5fd9389c40f975", "releases": ["R18-03_R1.4.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturelles Datenlayout- und Berechnungsdiagramm zur E2E-Kommunikationsabsicherung (AUTOSAR End-to-End Protocol Specification). Das Schaubild veranschaulicht die Byte- und Feldanordnung einer serialisierten Nachricht sowie den Datenfluss zur Berechnung der 8-Bit-Prüfsumme (CRC8) für das E2E-Profil 1 in der Variante 1A bei signalbasierter Kommunikation.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>DataId</strong>: Konfigurierte Identifikation des Datenstroms/der Botschaft, separat von der Nutzlast in die CRC-Berechnung einbezogen.\n</li><li><strong>CRC-Feld</strong>: 1-Byte-Feld (Byte 0, Bit-Offset 0) zur Aufnahme der resultierenden Prüfsumme.\n</li><li><strong>Alive Counter / Nibble 0xF</strong>: 1 Byte (Byte 1), unterteilt in das obere Halbbyte mit dem statischen Bitmuster <code>0xF</code> (entsprechend <code>unusedBitPattern = 0xFF</code>) und das untere Halbbyte mit dem dynamischen 4-Bit-Zähler (<code>Counter</code>, Bit-Offset 8 bis 11).\n</li><li><strong>Sig1 / Nutzsignale</strong>: Serialisierte Nutzsignalbereiche über mehrere Byteblöcke.\n</li><li><strong>Leere Bereiche / Unused Bits (<code>0xFF</code>, Leerfelder)</strong>: Nicht durch Nutzsignale belegte Bytes bzw. Padding-Bereiche innerhalb des Datenbereichs.\n</li><li><strong>Berechnungsvorschrift</strong>: <code>CRC := CRC8 over (1) Data Id, (2) all serialized signal (including empty areas, excluding CRC byte itself)</code>.\n</li><li><strong>Eingangsschnittstelle für Berechnung</strong>: Geschweifte Klammer spannt über den gesamten Datenstrom ab Byte 1 (unter Ausschluss des CRC-Bytes) und wird zusammen mit <code>DataId</code> über gerichtete Pfeile in das CRC-Byte zurückgeführt.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Zusammensetzen bzw. Serialisieren der Nutzsignale (<code>Sig1</code>) und des aktuellen Alive-Counters (<code>Counter</code> im unteren Nibble von Byte 1 mit <code>0xF</code> im oberen Nibble).\n</li><li>Auffüllen ungenutzter Byte- und Bitbereiche mit dem definierten Füllmuster (<code>0xFF</code> bzw. <code>0xF</code>).\n</li><li>Durchführung der CRC8-Berechnung über zwei Eingangsanteile:\n<ul class=\"fig-list\"><li>die vorkonfigurierte <code>DataId</code>,\n</li><li>alle serialisierten Signal- und Leerdaten ab Byte 1 bis zum Nachrichtenende (das CRC-Byte selbst wird explizit ausgespart).\n</li></ul>\n</li><li>Eintragen des berechneten 8-Bit-CRC-Wertes in Byte 0 der serialisierten Botschaft.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Normative Vorgabe zur Berechnung von E2E-Profil 1 (Variante 1A) unter Nutzung von <code>Crc_CalculateCRC8()</code>.\n</li><li>Das CRC-Byte belegt Byte 0 (Bit-Offset 0) und darf nicht selbst in die CRC-Prüfsumme einfließen.\n</li><li>Der Alive-Counter belegt die niederwertigen 4 Bits von Byte 1; ungenutzte Bits sind mit dem Muster <code>0xFF</code> zu belegen (<code>unusedBitPattern</code>).\n</li><li>Nicht signalbelegte Bytes (Leerbereiche) müssen im PDU-Puffer initialisiert und lückenlos in die Prüfsummenberechnung einbezogen werden.\n</li><li>Die <code>DataId</code> wird gemäß Konfigurationsmodus (z. B. <code>E2E_P01_DATAID_BOTH</code>) in die Prüfsummenberechnung eingespeist.\n</li></ul>"}], "trans": [{"from": "FIG-f3b8cf223c55c71f", "to": "FIG-ab5fd9389c40f975", "fr": "R17-10_R1.2.0", "tr": "R18-03_R1.4.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-ab5fd9389c40f975", "to": "FIG-f3b8cf223c55c71f", "fr": "R18-03_R1.4.0", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
